SELECT reader_key,toUnixTimestamp64Milli(created_at) AS created_ms,author_key,doc_id,group_id FROM (SELECT *,row_number() OVER (PARTITION BY reader_key,created_at,author_key,doc_id,group_id ORDER BY version DESC,deleted DESC) AS rn FROM fanout WHERE reader_key IN (unhex('616c696365'),unhex('626f62'))) WHERE rn=1 AND deleted=0 ORDER BY reader_key,created_ms DESC,doc_id DESC,author_key DESC,group_id
